//! Function-level comparison with `tests/cases.tsv`, generated by
//! `research/work-items/RE-005-node115-event-context-id/gen_oracle.py` from public
//! specifications before this crate was written. It compares this reconstruction with
//! a separately written model of the same reading of the node bytes; it is NOT a
//! comparison with a node run. Rows use arbitrary third values and arbitrary `a`/`b`,
//! which the spot-deploy call site never produces (it passes 0 as the third value).
use node115_event_context_id::*;

fn decode(text: &str) -> Vec<u8> {
    assert_eq!(text.len() % 2, 0);
    (0..text.len() / 2).map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).unwrap()).collect()
}

struct Row {
    group: String,
    mode: u8,
    a: u64,
    b: u64,
    c: u64,
    source: Source,
    preimage: Option<Vec<u8>>,
    base: Vec<u8>,
    context: Vec<u8>,
}

fn rows() -> Vec<Row> {
    include_str!("cases.tsv")
        .lines()
        .filter(|line| !line.starts_with('#'))
        .map(|line| {
            let f: Vec<&str> = line.split('\t').collect();
            assert_eq!(f.len(), 10, "{line}");
            Row {
                group: f[1].to_string(),
                mode: f[2].parse().unwrap(),
                a: u64::from_str_radix(f[3], 16).unwrap(),
                b: u64::from_str_radix(f[4], 16).unwrap(),
                c: u64::from_str_radix(f[5], 16).unwrap(),
                source: match f[6] {
                    "arith" => Source::Arithmetic,
                    "abi" => Source::Abi,
                    "msgpack" => Source::MessagePack,
                    other => panic!("unknown source {other}"),
                },
                preimage: (f[7] != "-").then(|| decode(f[7])),
                base: decode(f[8]),
                context: decode(f[9]),
            }
        })
        .collect()
}

#[test]
fn function_level_corpus_matches_spec_derived_expectations() {
    let rows = rows();
    assert_eq!(rows.len(), 613);
    let mut seen = [0usize; 3];
    for row in &rows {
        let at = format!("{} mode={} a={:#x} b={:#x} c={:#x}", row.group, row.mode, row.a, row.b, row.c);
        assert_eq!(select_source(row.mode, row.a), row.source, "source: {at}");
        match row.source {
            Source::Arithmetic => {
                assert!(row.preimage.is_none());
                seen[0] += 1;
            }
            Source::Abi => {
                assert_eq!(row.preimage.as_deref(), Some(&abi_preimage(row.a, row.b, row.c)[..]), "abi preimage: {at}");
                seen[1] += 1;
            }
            Source::MessagePack => {
                let packed = message_pack_preimage(row.a, row.b, row.c);
                assert_eq!(row.preimage.as_deref(), Some(packed.as_slice()), "msgpack preimage: {at}");
                seen[2] += 1;
            }
        }
        assert_eq!(base_bytes(row.mode, row.a, row.b, row.c).to_vec(), row.base, "base: {at}");
        assert_eq!(event_context(row.mode, row.a, row.b, row.c).to_vec(), row.context, "context: {at}");
    }
    assert!(seen.iter().all(|&n| n >= 100), "every branch must be well covered: {seen:?}");
}

#[test]
fn spot_deploy_call_site_passes_third_value_zero() {
    for row in rows().iter().filter(|row| row.c == 0) {
        assert_eq!(
            spot_deploy_charge_context(1, row.mode, row.a, row.b).to_vec(),
            row.context,
            "{} mode={} a={:#x} b={:#x}",
            row.group,
            row.mode,
            row.a,
            row.b
        );
    }
}

/// Each block is: base, mode^1, a+1, b+1, c+1. `a`, `b`, `c` always reach the result;
/// the mode only chooses the branch, so the mode variant differs exactly when the
/// branch differs (the mode byte is not hashed or written to the output).
#[test]
fn one_field_changes_and_mode_only_selects_the_branch() {
    let pairs: Vec<Row> = rows().into_iter().filter(|row| row.group == "one-field-pair").collect();
    assert_eq!(pairs.len(), 20);
    let mut mode_changed_branch = 0;
    for case in pairs.chunks(5) {
        for (i, other) in case.iter().enumerate().skip(2) {
            assert_ne!(case[0].context, other.context, "variant {i} equals the base");
            for later in &case[i + 1..] {
                assert_ne!(other.context, later.context);
            }
        }
        assert_eq!(case[0].context == case[1].context, case[0].source == case[1].source);
        mode_changed_branch += usize::from(case[0].source != case[1].source);
    }
    assert_eq!(mode_changed_branch, 1, "one of the four base rows crosses a branch with mode^1");
}
